 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Terms of Use Consent</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: #121a2f;
       --panel-border: #25304c;
       --text: #e8ecf7;
       --muted: #a8b3cf;
       --accent: #7c9cff;
       --accent-strong: #9eb3ff;
       --danger: #ff7a90;
       --focus: #c7d2fe;
       --shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
     }

     * {
       box-sizing: border-box;
     }

     html,
     body {
       min-height: 100%;
     }

     body {
       margin: 0;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(124, 156, 255, 0.14), transparent 30%),
         linear-gradient(180deg, #070b16 0%, var(--bg) 100%);
       color: var(--text);
       line-height: 1.5;
     }

     main {
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .card {
       width: min(100%, 460px);
       padding: 32px;
       border: 1px solid var(--panel-border);
       border-radius: 20px;
       background: rgba(18, 26, 47, 0.92);
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
     }

     h1 {
       margin: 0 0 8px;
       font-size: clamp(1.5rem, 2vw, 1.85rem);
       line-height: 1.15;
     }

     p {
       margin: 0;
     }

     .lede {
       color: var(--muted);
       margin-bottom: 24px;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 10px;
       padding: 16px;
       border: 1px solid rgba(148, 163, 184, 0.18);
       border-radius: 16px;
       background: rgba(255, 255, 255, 0.03);
     }

     .checkbox-row {
       display: grid;
       grid-template-columns: 20px 1fr;
       gap: 12px;
       align-items: start;
     }

     input[type="checkbox"] {
       width: 20px;
       height: 20px;
       margin: 2px 0 0;
       accent-color: var(--accent);
     }

     label {
       color: var(--text);
       font-weight: 600;
       cursor: pointer;
     }

     .required {
       color: var(--accent-strong);
       font-weight: 700;
     }

     .helper,
     .error {
       font-size: 0.94rem;
     }

     .helper {
       color: var(--muted);
     }

     .error {
       color: var(--danger);
       display: none;
     }

     .form-field[data-invalid="true"] {
       border-color: rgba(255, 122, 144, 0.55);
       background: rgba(255, 122, 144, 0.06);
     }

     .form-field[data-invalid="true"] .error {
       display: block;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.35rem;
       background: linear-gradient(180deg, var(--accent-strong), var(--accent));
       color: #0b1020;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 12px 28px rgba(124, 156, 255, 0.28);
     }

     button:hover {
       filter: brightness(1.05);
     }

     button:focus-visible,
     input:focus-visible,
     label:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .success {
       min-height: 1.5rem;
       color: #b6f3ca;
       font-weight: 600;
     }

     @media (max-width: 420px) {
       .card {
         padding: 24px;
       }

       .form-field {
         padding: 14px;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="consent-title">
       <h1 id="consent-title">Terms of Use</h1>
       <p class="lede">Please review and agree before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field" id="consent-field">
           <div class="checkbox-row">
             <input
               id="agree-terms"
               name="agreeTerms"
               type="checkbox"
               required
               aria-describedby="agree-help"
             >
             <label for="agree-terms">
               I agree to the Terms of Use <span class="required" aria-hidden="true">*</span>
             </label>
           </div>
           <p id="agree-help" class="helper">You must agree to continue.</p>
           <p id="agree-error" class="error" role="alert">Error: Please agree to the Terms of Use.</p>
         </div>

         <button type="submit">Continue</button>
         <p class="success" id="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('agree-terms');
     const field = document.getElementById('consent-field');
     const status = document.getElementById('form-status');

     function setInvalidState(isInvalid) {
       field.dataset.invalid = String(isInvalid);
       if (isInvalid) {
         checkbox.setAttribute('aria-invalid', 'true');
         checkbox.setAttribute('aria-describedby', 'agree-help agree-error');
       } else {
         checkbox.removeAttribute('aria-invalid');
         checkbox.setAttribute('aria-describedby', 'agree-help');
       }
     }

     form.addEventListener('submit', (event) => {
       if (!checkbox.checked) {
         event.preventDefault();
         setInvalidState(true);
         status.textContent = '';
         checkbox.focus();
         return;
       }

       event.preventDefault();
       setInvalidState(false);
       status.textContent = 'Thanks — your consent has been recorded.';
     });

     checkbox.addEventListener('change', () => {
       if (checkbox.checked) {
         setInvalidState(false);
         status.textContent = '';
       }
     });
   </script>
 </body>
 </html>

